-- Programa Indique e Ganhe. Execute após MIGRACAO-COBRANCAS.sql.
-- Valores monetários são sempre centavos; não há exclusão de histórico financeiro.
BEGIN;
CREATE TABLE referral_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), active boolean NOT NULL DEFAULT true, commission_bps integer NOT NULL DEFAULT 500 CHECK(commission_bps BETWEEN 0 AND 10000), commission_mode text NOT NULL DEFAULT 'recurring' CHECK(commission_mode IN ('recurring','first_payment')), safety_days integer NOT NULL DEFAULT 7 CHECK(safety_days BETWEEN 0 AND 365), minimum_payout_cents integer NOT NULL DEFAULT 5000 CHECK(minimum_payout_cents>=0), discount_enabled boolean NOT NULL DEFAULT false, discount_type text CHECK(discount_type IN ('percent','fixed')), discount_value integer NOT NULL DEFAULT 0 CHECK(discount_value>=0), discount_cycles integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO referral_settings(id) VALUES(true) ON CONFLICT DO NOTHING;
CREATE TABLE referral_codes (id text PRIMARY KEY, representative_id text NOT NULL UNIQUE REFERENCES representatives(id), code text NOT NULL, code_normalized text NOT NULL UNIQUE, commission_bps integer, active boolean NOT NULL DEFAULT true, pix_key_type text CHECK(pix_key_type IN ('cpf','cnpj','phone','email','random')), pix_key_ciphertext text, pix_holder_name text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE referrals (id text PRIMARY KEY, referrer_representative_id text NOT NULL REFERENCES representatives(id), referred_representative_id text NOT NULL UNIQUE REFERENCES representatives(id), referral_code_id text NOT NULL REFERENCES referral_codes(id), subscription_id text UNIQUE REFERENCES subscriptions(id), code_used text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), corrected_at timestamptz, corrected_by text);
CREATE TABLE referral_commissions (id text PRIMARY KEY, referral_id text NOT NULL REFERENCES referrals(id), invoice_id text NOT NULL UNIQUE REFERENCES billing_invoices(id), referrer_representative_id text NOT NULL REFERENCES representatives(id), referred_representative_id text NOT NULL REFERENCES representatives(id), base_cents integer NOT NULL CHECK(base_cents>=0), commission_bps integer NOT NULL CHECK(commission_bps BETWEEN 0 AND 10000), amount_cents integer NOT NULL CHECK(amount_cents>=0), status text NOT NULL CHECK(status IN ('pending','released','paid','cancelled')), available_at timestamptz, closing_id text, created_at timestamptz NOT NULL DEFAULT now(), cancelled_at timestamptz, cancellation_reason text);
CREATE TABLE referral_closings (id text PRIMARY KEY, competence char(7) NOT NULL, referrer_representative_id text NOT NULL REFERENCES representatives(id), amount_cents integer NOT NULL CHECK(amount_cents>=0), status text NOT NULL CHECK(status IN ('awaiting_payment','paid','rejected','blocked')), due_date date NOT NULL, paid_at timestamptz, paid_by text, note text, receipt_reference text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(competence,referrer_representative_id));
ALTER TABLE referral_commissions ADD CONSTRAINT referral_commissions_closing_fk FOREIGN KEY(closing_id) REFERENCES referral_closings(id);
CREATE TABLE referral_audit_logs (id bigserial PRIMARY KEY, actor_representative_id text REFERENCES representatives(id), action text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX referral_commissions_referrer_status ON referral_commissions(referrer_representative_id,status,created_at DESC);
CREATE INDEX referrals_referrer ON referrals(referrer_representative_id,created_at DESC);
COMMIT;
